sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float reach;
layout(color) uniform half4 color;
uniform float alpha;
uniform float fade;
uniform float fill;
uniform float solidity;
uniform float samples;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a)) * reach;
    float shade = 0.0;
    float n = floor(clamp(samples, 1.0, 512.0) + 0.5);
    for (int i = 1; i <= 512; i++) {
        if (float(i) > n) break;
        float t = float(i) / n;
        float hit = float(image.eval(coord - d * t).a) * (1.0 - fade * t) * (1.0 - pow(1.0 - clamp(solidity, 0.0, 1.0), 1.35 + 4.15 * (1.0 - t)));
        shade = max(shade, hit);
    }
    float sa = shade * clamp(alpha, 0.0, 1.0) * float(color.a);
    half4 s = half4(half3(color.rgb) * half(sa), half(sa));
    half4 body = src * half(clamp(fill, 0.0, 1.0));
    return body + s * (1.0 - body.a);
}
